queries_and_chunks = [
    {"query": "how to reset a password", "relevant_chunk": "To reset your password, go to account settings."},
    {"query": "refund policy timeline", "relevant_chunk": "Refunds are processed within thirty days of purchase."},
]

def build_training_pairs(data):
    # pairs each query with its relevant chunk (similar) and other chunks (dissimilar)
    pairs = []
    for i, item in enumerate(data):
        pairs.append({"text_a": item["query"], "text_b": item["relevant_chunk"], "label": "similar"})
        for j, other in enumerate(data):
            if i != j:
                pairs.append({"text_a": item["query"], "text_b": other["relevant_chunk"], "label": "dissimilar"})
    return pairs

training_pairs = build_training_pairs(queries_and_chunks)
print("Generated training pairs:\n")
for pair in training_pairs:
    print(f"  [{pair['label']}] {pair['text_a']!r} <-> {pair['text_b']!r}")

print(f"\nTotal pairs: {len(training_pairs)}")
